<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useServiceContext} from '@/composables/useServiceContext'
import {isPreferences,isCollectionEntry,isPage,isApplied,query,kinds,publicLink,type Preferences,type CollectionEntry} from '@/api/modules/clientServices'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
const route=useRoute(),ui=useServiceContext(()=>null),{error,notice,busy,pending}=ui,history=computed(()=>route.params.section==='history')
const preferences=ref<Preferences|null>(null),items=ref<CollectionEntry[]>([]),cursor=ref<string|number|null>(null),kind=ref(''),loading=ref(false),loaded=ref(false)
const locked=computed(()=>busy.value||!!pending.value||loading.value)
let initialized=false
function initialize(){initialized=true;void load()}
let serial=0
function reset(){serial++;preferences.value=null;items.value=[];cursor.value=null;loading.value=false;loaded.value=false}
async function load(more=false){error.value=null;if(loading.value||more&&!cursor.value)return;const n=++serial,old=more?cursor.value:null;loading.value=true;if(!more){items.value=[];cursor.value=null;loaded.value=false;const p=await ui.read('/me/collections/preferences',isPreferences);if(n!==serial)return;preferences.value=p;if(!preferences.value){loading.value=false;return}}const r=await ui.read('/me/collections/'+(history.value?'history':'favorites')+query({kind:kind.value,cursor:old,limit:20}),isPage(isCollectionEntry));if(n!==serial)return;loading.value=false;if(!r)return;if(old!==null&&r.next_cursor===old){ui.fail('清单分页未更新，请刷新。');return}items.value=more?[...items.value,...r.items]:r.items;cursor.value=r.next_cursor;loaded.value=true}
async function toggle(){const p=preferences.value;if(!p||locked.value)return;const enabled=!p.history_enabled;if(!enabled&&!window.confirm('关闭会清空浏览记录，不会删除订单或已购买许可。确认关闭？'))return;await ui.write('/me/collections/preferences',{history_enabled:enabled},isPreferences,async()=>{await load();notice.value=enabled?'已开启；之后实际打开公开详情才会记录。':'已关闭并清空浏览记录。'},{ifMatch:p.object_version});if(error.value?.status===412)await load()}
async function remove(item:CollectionEntry){if(locked.value)return;if(history.value){if(!preferences.value)return;await ui.write(`/me/collections/history/${item.kind}/${item.target_id}`,undefined,isPreferences,async()=>{await load()},{method:'DELETE',ifMatch:preferences.value.object_version})}else await ui.write('/me/collections/favorites',{kind:item.kind,target_id:item.target_id,saved:false},isApplied,async()=>{await load();notice.value='已重新读取收藏状态；取消收藏不影响已购买许可。'});if(error.value?.status===412)await load()}
async function clearHistory(){if(!preferences.value||locked.value||!window.confirm('清空全部浏览记录？开关保持当前状态，订单和许可不会删除。'))return;await ui.write('/me/collections/history',undefined,isPreferences,async()=>{items.value=[];cursor.value=null;await load();notice.value='已清空浏览记录。'},{method:'DELETE',ifMatch:preferences.value.object_version});if(error.value?.status===412)await load()}
watch(ui.revision,()=>{reset();if(initialized&&ui.ready.value)void load()},{flush:'sync'})
watch(kind,()=>{ui.cancelReads();serial++;loading.value=false;items.value=[];cursor.value=null;void load()})
</script>
<template><ServiceWorkspace :title="history?'我的浏览记录':'我的收藏'" intro="这份清单属于当前登录账号。切换个人或机构办理身份不会产生另一份私人清单。" account-only :locked="locked" :error="error" :notice="notice" @ready="initialize"><div class="service-tabs"><RouterLink to="/me/collections/favorites">我的收藏</RouterLink><RouterLink to="/me/collections/history">浏览记录</RouterLink><RouterLink to="/discovery">查找公开内容</RouterLink></div><section v-if="pending" class="service-pending"><p>操作结果待确认，已保留原内容。</p><button class="outline" :disabled="busy" @click="ui.retry">恢复原请求</button></section><section v-if="preferences" class="supply-card"><h2>浏览记录 {{preferences.history_enabled?'已开启':'已关闭'}}</h2><p>仅在开启后记录实际打开的公开艺人、影片和通告详情，最多保留 {{preferences.history_days}} 天、{{preferences.history_max_entries}} 条。</p><div class="service-actions"><button class="outline" :disabled="locked" @click="toggle">{{preferences.history_enabled?'关闭并清空浏览记录':'开启浏览记录'}}</button><button v-if="history" class="outline" :disabled="locked||!items.length" @click="clearHistory">清空浏览记录</button></div></section><section class="supply-card"><div class="service-form"><label>内容类别<select v-model="kind" :disabled="locked"><option value="">全部</option><option v-for="k in (['ARTIST','STOCK','NOTICE'] as const)" :key="k" :value="k">{{kinds[k]}}</option></select></label><button class="outline" :disabled="locked||loading" @click="load()">刷新当前清单</button></div><p v-if="loading" role="status">正在读取…</p><article v-for="item in items" :key="item.kind+item.target_id" class="service-result"><p class="service-muted">{{kinds[item.kind]}} · {{new Date(item.recorded_at).toLocaleString()}}</p><h2>{{item.availability==='AVAILABLE'?item.title||'查看当前内容':'内容已不可用'}}</h2><p v-if="item.availability==='AVAILABLE'">{{item.city}}</p><div class="service-actions"><RouterLink v-if="item.availability==='AVAILABLE'" :to="publicLink(item.kind,item.target_id)" class="button-link outline">查看当前详情</RouterLink><button class="outline" :disabled="locked" @click="remove(item)">{{history?'删除这条浏览记录':'取消收藏'}}</button></div></article><p v-if="loaded&&!items.length&&!cursor&&!error">{{history&&!preferences?.history_enabled?'浏览记录当前关闭。':'这份清单中暂无记录。'}}</p><p v-if="!items.length&&cursor">本页暂无可显示记录，可继续读取。</p><button v-if="cursor" class="outline" :disabled="locked||loading" @click="load(true)">继续读取清单</button></section></ServiceWorkspace></template>
